const b = $input.first().json.body || $input.first().json;
const email = b?.data?.buyer?.email || b?.customer?.email || b?.email || '';
const transaccion = b?.data?.purchase?.transaction || b?.receipt || b?.order_id || b?.transaction_id || '';
// plataforma y motivo: alimentan el registro de reembolsos del CRM
// (trazabilidad). Cada plataforma manda el motivo en un campo distinto.
const plataforma = b?.data?.purchase ? 'Hotmart' : (b?.receipt ? 'ClickBank' : (b?.order_id ? 'ThriveCart' : (b?.plataforma || '')));
const motivo = b?.data?.purchase?.refund_reason || b?.refund_reason || b?.reason || b?.motivo || '';
return [{ json: { email, transaccion, plataforma, motivo } }];
